assert(numberOfChecks % 2 == 1);
static std::random_device rd;
static std::mt19937 gen(rd());
std::uniform_real_distribution<double> dist(-1.0, 1.0);

int inside = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    cg3::Point3d dir(dist(gen), dist(gen), dist(gen));
    if (dir.lengthSquared() < 1e-12) {
        --i;
        continue;
    }
    dir.normalize();

    cg3::Point3d far = p + dir * (bb.diag() * 2.0);
    int hits = numberIntersectedPrimitives(p, far);
    if (hits % 2 == 1) {
        ++inside;
    }
}
return inside > numberOfChecks / 2;

